"use client";

import React from "react";

import VerticalTiles from "@/registry/open-source/stripes-preloader";

export default function Usage() {
	return (
		<div className="h-screen w-full flex items-center justify-center relative overflow-hidden bg-black">
			<VerticalTiles rerun>
				<span>Some content</span>
			</VerticalTiles>{" "}
		</div>
	);
}

import React, { useCallback, useEffect, useRef, useState } from "react";

import { cn } from "@/registry/utilities/utils";
import { motion, useInView } from "motion/react";

interface Tile {
	id: number;
	width: number;
	order: number;
}

interface VerticalTilesProps {
	tileClassName?: string;
	minTileWidth?: number;
	animationDuration?: number;
	animationDelay?: number;
	stagger?: number;
	children?: React.ReactNode;
	rerun?: boolean;
}

export default function VerticalTiles({
	tileClassName,
	minTileWidth = 32,
	animationDuration = 0.5,
	animationDelay = 1,
	stagger = 0.05,
	children,
	rerun,
}: VerticalTilesProps) {
	const [tiles, setTiles] = useState<Tile[]>([]);
	const containerRef = useRef<HTMLDivElement>(null);
	const isInView = useInView(containerRef, {
		once: rerun || false,
		amount: 0.3,
	});

	const calculateTiles = useCallback(() => {
		if (containerRef.current) {
			const { offsetWidth: width, offsetHeight: _ } = containerRef.current;
			const tileCount = Math.max(3, Math.floor(width / minTileWidth));
			const tileWidth = width / tileCount + 1;

			const newTiles = Array.from({ length: tileCount }, (_, index) => ({
				id: index,
				width: tileWidth,
				order: Math.abs(index - Math.floor((tileCount - 1) / 2)),
			}));

			setTiles(newTiles);
		}
	}, [minTileWidth]);

	useEffect(() => {
		calculateTiles();
		const resizeObserver = new ResizeObserver(calculateTiles);
		if (containerRef.current) {
			resizeObserver.observe(containerRef.current);
		}
		return () => resizeObserver.disconnect();
	}, [calculateTiles]);

	return (
		<div ref={containerRef} className="relative overflow-hidden">
			{children}

			<div className="absolute inset-0 flex">
				{tiles.map((tile) => (
					<motion.div
						key={tile.id}
						className={cn("bg-gray-800", tileClassName)}
						style={{
							width: tile.width,
							position: "absolute",
							left: `${(tile.id * 100) / tiles.length}%`,
							top: 0,
							height: "100%",
						}}
						initial={{ y: 0 }}
						animate={isInView || rerun ? { y: "100%" } : { y: 0 }}
						transition={{
							duration: animationDuration,
							delay: animationDelay + tile.order * stagger,
							ease: [0.45, 0, 0.55, 1],
						}}
					/>
				))}
			</div>
		</div>
	);
}

import registry from "@/registry.json";
import { clsx, type ClassValue } from "clsx";
import type { RegistryItem } from "shadcn/registry";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const components = registry.items as unknown as RegistryItem[];

export const getComponents = (selectedTags: any[] = []): RegistryItem[] => {
	return selectedTags.length
		? components.filter((component) =>
				selectedTags.every(
					(tag) => component.meta?.tags?.includes(tag) ?? false
				)
			)
		: components;
};

export const getComponentsByNames = (names: string[]): RegistryItem[] => {
	const componentsMap = new Map(components.map((comp) => [comp.name, comp]));

	return names
		.map((name) => componentsMap.get(name))
		.filter((comp): comp is RegistryItem => comp !== undefined);
};

export const getAvailableTags = (selectedTags: any[]): any[] => {
	if (!selectedTags.length) return [];

	// Get all components that have all the selected tags
	const matchingComponents = components.filter((component) =>
		selectedTags.every((tag) => component.meta?.tags?.includes(tag) ?? false)
	);

	// Get all unique tags from the matching components
	const availableTags = new Set<any>();
	matchingComponents.forEach((component) => {
		component.meta?.tags?.forEach((tag: any) => {
			if (!selectedTags.includes(tag)) {
				availableTags.add(tag);
			}
		});
	});

	return Array.from(availableTags);
};

export const convertRegistryPaths = (content: string): string => {
	return content
		.replace(/@\/registry\/default\/ui/g, "@/components/ui")
		.replace(/@\/registry\/default\/compositions/g, "@/components")
		.replace(/@\/registry\/default\/hooks/g, "@/hooks")
		.replace(/@\/registry\/default\/lib/g, "@/lib");
};
